using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class StringKeyedFieldDroppedTests
{
    private readonly ITestOutputHelper logger;

    public StringKeyedFieldDroppedTests(ITestOutputHelper logger)
    {
        this.logger = logger;
    }

    [Fact]
    public async Task StringKeyedFieldAppearsInGeneratedFormatter()
    {
        string source = """
            using MessagePack;

            namespace TestNs
            {
                [MessagePackObject]
                public class MyObject
                {
                    [Key("myField")]
                    public int MyFieldValue;
                }

                [GeneratedMessagePackResolver]
                partial class MyResolver
                {
                }
            }
            """;

        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        var frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var references = frameworkRefs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();

        var compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new ISourceGenerator[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGenerators(compilation);
        GeneratorDriverRunResult result = driver.GetRunResult();

        foreach (var r in result.Results)
        {
            Assert.Null(r.Exception);
        }

        string allGenerated = string.Join("\n", result.GeneratedTrees.Select(t => t.ToString()));
        this.logger.WriteLine(allGenerated);

        Assert.Contains("MyObject", allGenerated);
        Assert.Contains("MyFieldValue", allGenerated);
    }
}
